files.hooks/mod.ts:
// draft-pane's one function-hooks module (the validator admits one per plugin). Reads the
// ```draft blocks the model posts in the transcript, shows every one still open in a pane
// beside it, and lets the person drag a span of the body to comment on it, or write one comment
// on the whole draft. A body is drawn as a column of segments, cut at each line that already
// carries a comment, so a comment and its input sit right under the line they belong to; one
// `Client` draws each segment. One Submit sends every comment as one prompt that quotes each
// span; one Approve sends nothing but a plain approval line. The transcript is the source of
// truth: every draft shown here is an assistant message, and every piece of feedback sent is a
// prompt that quotes it back.
//
// A block may name a file instead of carrying the draft's text (block.ts's `Draft.file`). Every
// `reparse` rereads that file for each open file draft and fills `draft.body` from it, so the
// pane always shows what is on disk as of the newest parse; a read failure is kept in
// `state.readErrors` and drawn in place of the body rather than logged, since it is the person's
// to see, not the operator's.
//
// Must NOT know about: what a draft says, or how a ```draft block or a feedback prompt is
// written — block.ts owns that syntax, and this file only calls its exported functions; how a
// drag maps to a character range — draft-selection.ts owns that, and this file only reads what
// it posts; how a body splits into segments or how an offset moves between a segment's own text
// and the whole body — segments.ts owns that, and this file only calls its exported functions;
// how the desktop tree looks — desktop.ts owns that, and this file only gives it each draft's
// data and closures (`desktopDraftModelOf`).
//
// It loads only where Claude Code has function hooks enabled. The engine's validator reads this
// file statically, so every call on `$` is spelled `$.noun.event(...)` and `$` is handed only
// to the function declaration at the top of the file (`hostOf`); the rest of the module holds a
// `Host`, a bundle of closures built once at `session.start`. The transcript is parsed on
// `session.start` and `turn.complete` only, kept in `state.open`; `ui.render` draws from state
// alone and never reads the transcript itself.

import type { Elements, On, RenderElement, SessionMessage } from 'claude-code'
import { approvalTextOf, draftsByNumberOf, feedbackTextOf, identityOf, openDraftsOf, revisionTrailOf, trimmedBodyOf } from './block'
import type { Draft, OpenDraft } from './block'
import {
  EMPTY_FEEDBACK,
  commentCountOf,
  hasUnsentTextOf,
  selectionMessageOf,
  shortQuoteOf,
  withoutTrailingNewlinesOf,
  withSelection,
  withSpanCommitted,
  withSpanRemoved,
  withSpanText,
  withWholeCommitted,
  withWholeOpen,
  withWholeRemoved,
  withWholeText,
} from './feedback'
import type { Feedback } from './feedback'
import { anchorLineOf, segmentsOf, toAbsolute, toLocal } from './segments'
import type { Segment } from './segments'
import { desktopDraftOf, desktopEmptyOf, fileHrefOf } from './desktop'
import type { DesktopDraft, DesktopUi, View } from './desktop'
import { unifiedDiffOf } from './diff'

const PANE_ID = 'draft-pane'
const COMMAND = 'draft-pane'
const STORE_KEY = 'wantsOpen'

type Host = {
  messages: () => Promise<readonly SessionMessage[]>
  submit: (text: string) => Promise<{ drop?: string }>
  status: (text: string | undefined) => void
  open: (focus: boolean) => Promise<void>
  close: () => Promise<void>
  invalidate: () => void
  log: (text: string) => void
  register: () => Promise<unknown>
  storeGet: (key: string) => Promise<unknown>
  storeSet: (key: string, value: unknown) => Promise<void>
  focus: (key: string) => Promise<{ deny?: string }>
  sleep: (ms: number) => Promise<void>
  readFile: (path: string) => Promise<string>
}

type State = {
  host: Host | null
  isOpen: boolean
  wantsOpen: boolean
  open: OpenDraft[]
  // The session's working directory (`e.cwd` at `session.start`), the base a file draft's
  // relative path reads against.
  cwd: string
  // A draft's pending feedback, by identity (block.ts's `identityOf`).
  feedback: Map<string, Feedback>
  // Identities a Submit or Approve already sent, this process only (see `submit`'s own note).
  sent: Set<string>
  isSubmitting: boolean
  // A file draft's read failure, by identity, computed from the draft as left after the failed
  // read (empty body). Drawn in place of the body; cleared once that identity is no longer open.
  readErrors: Map<string, string>
  // Every draft in the transcript by number (block.ts's `draftsByNumberOf`), kept so the desktop
  // can draw a revision's trail and its diff against the draft it revises.
  history: Map<number, Draft>
  // The desktop view each open draft shows, by identity; absent means `comment`.
  views: Map<string, View>
}

// The host is a bundle of closures over `$`, built once at `session.start`, so the rest of this
// file never holds `$` itself — the validator's rule, and also the seam a test fakes.
function hostOf($: any): Host {
  return {
    messages: () => $.session.messages(),
    submit: (text) => $.prompt.submit({ text }),
    status: (text) => $.ui.status(text),
    open: (focus) => $.ui.open({ id: PANE_ID, title: PANE_ID, ...(focus ? { focus: true } : {}) }),
    close: () => $.ui.close({ id: PANE_ID }),
    invalidate: () => $.ui.invalidate('ui.render'),
    log: (text) => $.ui.log(text),
    register: () => $.command.register({ name: COMMAND, description: 'Show or hide the draft-pane' }),
    storeGet: (key) => $.store.get(key),
    storeSet: (key, value) => $.store.set(key, value),
    focus: (key) => $.ui.focus({ requestId: PANE_ID, key }),
    sleep: (ms) => $.clock.sleep(ms),
    readFile: (path) => $.fs.read(path),
  }
}

function messageOf(error: unknown): string {
  return error instanceof Error ? error.message : String(error)
}

// A drag's release, or a `whole draft` button press, posts before the redraw that draws the
// comment `Input` exists: `$.ui.invalidate` only schedules that redraw (at most thirty a second
// for the shown pane), so a `focus` call right after can find no element under the key yet. The
// `deny` names that missing element rather than any other failure, so it is safe to retry on; ten
// tries at 50ms apart cover the slowest redraw cadence with room, without retrying a `deny` that
// means something else.
async function focusInput(host: Host, key: string): Promise<void> {
  try {
    for (let attempt = 0; attempt < 10; attempt += 1) {
      const result = await host.focus(key)
      if (result.deny === undefined) return
      if (attempt < 9) {
        await host.sleep(50)
      } else {
        host.log(`focus denied: ${result.deny}`)
      }
    }
  } catch (error) {
    host.log(`focus failed: ${messageOf(error)}`)
  }
}

// The drafts still worth drawing: `state.open` less whatever a Submit or Approve already sent.
// `sent` survives a `reparse` on purpose (see `submit`'s own note) so it, not `state.open`, is
// the filter applied here.
function visibleOf(state: State): OpenDraft[] {
  return state.open.filter((od) => !state.sent.has(identityOf(od.draft)))
}

function updateStatus(state: State): void {
  const host = state.host
  if (host === null) return
  const visible = visibleOf(state)
  if (state.isOpen || visible.length === 0) {
    host.status(undefined)
    return
  }
  const word = visible.length === 1 ? 'draft' : 'drafts'
  host.status(`${visible.length} open ${word} (/draft-pane)`)
}

// `$.store` is the plugin's own file, kept across sessions and hot reloads and shared by every
// session in every directory — one flag in it cannot mean "the pane is open", or a pane left
// open in one session would reopen empty at the start of every later one. It means the person
// wants the pane; the pane itself opens only once there is a draft worth showing it for. Used
// from `session.start` (by way of `reparse`, below) and from `reparse` itself on
// `turn.complete`, so a draft that appears mid-session opens the pane the same way one already
// open at session start does.
async function openIfWanted(state: State): Promise<void> {
  const host = state.host
  if (host === null || !state.wantsOpen || state.isOpen || visibleOf(state).length === 0) return
  try {
    // Not focused: opening on its own, unasked, must not take the keyboard away from whatever
    // the person is about to type.
    await host.open(false)
    state.isOpen = true
  } catch (error) {
    host.log(`reopen failed: ${messageOf(error)}`)
  }
}

// A file draft's body read fresh from disk, in parallel with every other open file draft's, so
// one missing file does not delay or fail the rest. Mutates `draft.body` in place (the draft is
// this `reparse`'s own, freshly parsed, so nothing else holds a reference yet) and records or
// clears `state.readErrors` under the identity that body leaves the draft with.
async function readFileDraft(state: State, host: Host, draft: Draft): Promise<void> {
  const path = draft.file
  if (path === null) return
  try {
    const text = await host.readFile(path)
    draft.body = trimmedBodyOf(text)
    state.readErrors.delete(identityOf(draft))
  } catch (error) {
    draft.body = ''
    state.readErrors.set(identityOf(draft), messageOf(error))
  }
}

// Re-reads the transcript into `state.open`, rereads every open file draft's file, drops any
// pending feedback or read error whose draft is no longer open (approved, submitted or gone from
// the transcript, on some other path), and redraws. Wrapped whole in a try/catch: a hook is
// fail-open, so a parse failure must not vanish silently — it goes to `host.log` once instead.
async function reparse(state: State): Promise<void> {
  const host = state.host
  if (host === null) return
  try {
    const messages = await host.messages()
    state.open = openDraftsOf(messages)
    state.history = draftsByNumberOf(messages)
    await Promise.all(state.open.map((od) => readFileDraft(state, host, od.draft)))
    const openIdentities = new Set(state.open.map((od) => identityOf(od.draft)))
    for (const identity of state.feedback.keys()) {
      if (!openIdentities.has(identity)) state.feedback.delete(identity)
    }
    for (const identity of state.readErrors.keys()) {
      if (!openIdentities.has(identity)) state.readErrors.delete(identity)
    }
    for (const identity of state.views.keys()) {
      if (!openIdentities.has(identity)) state.views.delete(identity)
    }
    host.invalidate()
    await openIfWanted(state)
    updateStatus(state)
  } catch (error) {
    host.log(`reparse failed: ${messageOf(error)}`)
  }
}

function feedbackOf(state: State, identity: string): Feedback {
  return state.feedback.get(identity) ?? EMPTY_FEEDBACK
}

// A draft's body cut into segments, each ending at the line under which a comment sits (its
// anchor line): one per committed span, plus the pending selection when there is one. Called
// from both sides of the `ui.message` handler and `draftBoxOf`, so a segment index posted by one
// always means the same segment to the other.
function segmentsForDraft(draft: Draft, feedback: Feedback): Segment[] {
  const lines = draft.body.split('\n')
  const anchorLines = feedback.spans.map((span) => anchorLineOf(lines, span))
  if (feedback.selection !== null) anchorLines.push(anchorLineOf(lines, feedback.selection))
  return segmentsOf(lines, anchorLines)
}

// `isSubmitting` guards a press arriving while a previous submit is still in flight. Sending
// nothing when there is no comment guards the other press pattern: focus already sitting on
// Submit, one Enter with nothing said, spending a whole turn on an empty prompt nobody chose.
async function submit(state: State, host: Host, draft: Draft): Promise<void> {
  if (state.isSubmitting) return
  const identity = identityOf(draft)
  const feedback = feedbackOf(state, identity)
  if (hasUnsentTextOf(feedback)) {
    host.status(`D${draft.number} has text in an input; press Enter to add it, or clear it`)
    return
  }
  if (commentCountOf(feedback) === 0) {
    host.status('add a comment or press Approve before Submit')
    return
  }

  state.isSubmitting = true
  try {
    const result = await host.submit(feedbackTextOf(draft, feedback.spans, feedback.whole))
    if (result.drop === undefined) {
      state.sent.add(identity)
      state.feedback.delete(identity)
      host.status(undefined)
      host.invalidate()
    }
    // A `drop` leaves the draft and its pending feedback exactly where they were, so the person
    // can press Submit again without redoing anything.
  } finally {
    state.isSubmitting = false
  }
}

// Approve refuses while there is a pending comment: a comment left unsent under an Approve
// would read, on the transcript, as if the person had nothing to say about it.
async function approve(state: State, host: Host, draft: Draft): Promise<void> {
  if (state.isSubmitting) return
  const identity = identityOf(draft)
  const feedback = feedbackOf(state, identity)
  // The kit cannot type into an Input, so this guard is never reached from mod.test.ts.
  if (hasUnsentTextOf(feedback)) {
    host.status(`D${draft.number} has text in an input; press Enter to add it, or clear it`)
    return
  }
  if (commentCountOf(feedback) > 0) {
    host.status(`D${draft.number} has comments; press Submit, or remove them first`)
    return
  }

  state.isSubmitting = true
  try {
    const result = await host.submit(approvalTextOf(draft))
    if (result.drop === undefined) {
      state.sent.add(identity)
      state.feedback.delete(identity)
      host.status(undefined)
      host.invalidate()
    }
  } finally {
    state.isSubmitting = false
  }
}

// The transitions behind an `Input` or a `Button`, each one line so the closure drawn beside it
// stays one line too (the test kit cannot type into an `Input`, so these are what feedback.test.ts
// covers instead).
// No `host.invalidate()` here: the `Input` already shows what the person types, so redrawing on
// every keystroke is wasted work, and it can move the cursor out from under the person's hands.
// The mirror kept in `state.feedback` exists so that a redraw triggered by something else (a
// `turn.complete`, another draft's own action) hands the typed text back rather than losing it.
function onSpanTextInput(state: State, host: Host, identity: string, text: string): void {
  state.feedback.set(identity, withSpanText(feedbackOf(state, identity), text))
}

function onSpanTextSubmit(state: State, host: Host, identity: string, text: string): void {
  state.feedback.set(identity, withSpanCommitted(feedbackOf(state, identity), text))
  host.invalidate()
}

function onSpanRemove(state: State, host: Host, identity: string, index: number): void {
  state.feedback.set(identity, withSpanRemoved(feedbackOf(state, identity), index))
  host.invalidate()
}

// No `host.invalidate()` here: the `Input` already shows what the person types, so redrawing on
// every keystroke is wasted work, and it can move the cursor out from under the person's hands.
// The mirror kept in `state.feedback` exists so that a redraw triggered by something else (a
// `turn.complete`, another draft's own action) hands the typed text back rather than losing it.
function onWholeTextInput(state: State, host: Host, identity: string, text: string): void {
  state.feedback.set(identity, withWholeText(feedbackOf(state, identity), text))
}

function onWholeTextSubmit(state: State, host: Host, identity: string, text: string): void {
  state.feedback.set(identity, withWholeCommitted(feedbackOf(state, identity), text))
  host.invalidate()
}

function onWholeRemove(state: State, host: Host, identity: string): void {
  state.feedback.set(identity, withWholeRemoved(feedbackOf(state, identity)))
  host.invalidate()
}

// Behind the `whole draft` button: opens the field the same way a drag opens the span one — ask
// for the keyboard, then move the ring onto the `Input` the next redraw will draw. `host.open`'s
// own failure is logged and swallowed, same as `ui.message`'s drag handler, so a denied request
// leaves the field open and drawn, just without focus.
async function openWholeInput(state: State, host: Host, identity: string, key: string): Promise<void> {
  state.feedback.set(identity, withWholeOpen(feedbackOf(state, identity), true))
  host.invalidate()
  try {
    await host.open(true)
  } catch (error) {
    host.log(`focus: open failed: ${messageOf(error)}`)
  }
  await focusInput(host, key)
}

// The real element types, so the typecheck refuses a prop the engine would refuse. One unknown
// prop drops the whole tree with no message. `Text` takes no `key`.
//
// This tree is the terminal's. The desktop draws its own tree (desktop.ts) from the same state
// and the same transitions; it uses the same five elements and adds `Svg`, `Markdown` and
// `Code`. `Ui` stays typed for both surfaces, so a prop that this tree uses is one that both
// declare. Other surfaces go to `next(e)`.
type DrawnSurface = 'terminal' | 'desktop'
type Ui = Pick<Elements[DrawnSurface], 'Box' | 'Button' | 'Text' | 'Input' | 'Client'>

function commentRowOf(ui: Ui, key: string, quote: string, comment: string, onRemove: () => void): RenderElement {
  const { Box, Button, Text } = ui
  return Box({
    key,
    flexDirection: 'row',
    columnGap: 1,
    children: [Button({ key: `${key}:remove`, label: 'x', onPress: onRemove }), Text({ dimColor: true, children: `> ${quote}` }), Text({ children: comment })],
  })
}

// The rows drawn right under segment `k`: one per committed span anchored on its last line, in
// ascending `start` order, then the pending selection's own quote and `Input` when it is
// anchored there too. A span keeps its index into `feedback.spans` for its key and its `onRemove`
// closure, even sorted here into a different display order, so removing one still removes the
// right one.
function segmentRowsOf(ui: Ui, key: string, draft: Draft, lines: readonly string[], segment: Segment, feedback: Feedback, state: State, host: Host, identity: string): RenderElement[] {
  const { Box, Text, Input } = ui
  const rows: RenderElement[] = feedback.spans
    .map((span, spanIndex) => ({ span, spanIndex }))
    .filter(({ span }) => anchorLineOf(lines, span) === segment.lastLine)
    .sort((a, b) => a.span.start - b.span.start)
    .map(({ span, spanIndex }) =>
      commentRowOf(ui, `${key}:c${spanIndex}`, shortQuoteOf(draft.body, span), span.comment, () => onSpanRemove(state, host, identity, spanIndex)),
    )

  const selection = feedback.selection
  if (selection !== null && anchorLineOf(lines, selection) === segment.lastLine) {
    rows.push(
      Box({
        key: `${key}:span-input-row`,
        flexDirection: 'column',
        children: [
          Text({ dimColor: true, children: `> ${shortQuoteOf(draft.body, selection)}` }),
          Input({
            key: `${key}:span-input`,
            label: 'comment',
            placeholder: 'Enter adds it; empty Enter drops the span',
            value: feedback.spanText,
            autoFocus: true,
            onInput: (value) => onSpanTextInput(state, host, identity, value),
            onSubmit: (value) => onSpanTextSubmit(state, host, identity, value),
          }),
        ],
      }),
    )
  }
  return rows
}

function draftBoxOf(ui: Ui, index: number, openDraft: OpenDraft, state: State, host: Host): RenderElement {
  const { Box, Button, Text, Input, Client } = ui
  const { draft, isDuplicate } = openDraft
  const identity = identityOf(draft)
  const feedback = feedbackOf(state, identity)
  const key = `d${index}`

  const children: RenderElement[] = [Text({ bold: true, children: `D${draft.number} ${draft.title}` })]
  if (isDuplicate) children.push(Text({ color: 'yellow', children: 'duplicate number' }))

  if (draft.file !== null) {
    children.push(Text({ dimColor: true, children: `file: ${draft.file}` }))
    const readError = state.readErrors.get(identity)
    if (readError !== undefined) {
      children.push(Text({ color: 'red', children: `cannot read the file: ${readError}` }))
      return Box({ key, flexDirection: 'column', rowGap: 1, children })
    }
    if (draft.body === '') {
      children.push(Text({ children: 'the file is empty' }))
      return Box({ key, flexDirection: 'column', rowGap: 1, children })
    }
  }

  const lines = draft.body.split('\n')
  const segments = segmentsForDraft(draft, feedback)
  const selection = feedback.selection

  segments.forEach((segment, k) => {
    const armedRange = selection === null ? null : toLocal(segment, selection)
    children.push(
      Client({
        key: `${key}:seg${k}`,
        // A string literal, not a constant: the validator reads a Client's `module` statically
        // and refuses any indirection, so the path is spelled out here rather than named once.
        module: './draft-selection.ts',
        props: { lines: segment.lines, ...(armedRange === null ? {} : { armedRange }) },
        width: '100%',
      }),
    )
    children.push(
      Box({
        key: `${key}:seg${k}:rows`,
        flexDirection: 'column',
        children: segmentRowsOf(ui, key, draft, lines, segment, feedback, state, host, identity),
      }),
    )
  })

  if (feedback.whole !== null) {
    const whole = feedback.whole
    children.push(
      Box({
        key: `${key}:whole`,
        flexDirection: 'row',
        columnGap: 1,
        children: [
          Button({ key: `${key}:whole:remove`, label: 'x', onPress: () => onWholeRemove(state, host, identity) }),
          Text({ children: `(whole draft) ${whole}` }),
        ],
      }),
    )
  }

  // Drawn only while `feedback.wholeOpen` is true, not from the first render: a real-terminal
  // round measured that, with an `Input` on screen from the start, no mouse event reached Claude
  // Code at all, in this pane or in the transcript, and that a pane holding only `Button` and
  // `Text` (grilling-pane's) was unaffected. The `whole draft` button below opens the field; Enter
  // closes it again, so at most one draft's `Input` is ever on screen.
  if (feedback.wholeOpen) {
    children.push(
      Box({
        key: `${key}:whole-input-row`,
        children: [
          Input({
            key: `${key}:whole-input`,
            label: 'whole draft',
            placeholder: 'comment on the whole draft',
            value: feedback.wholeText,
            autoFocus: true,
            onInput: (value) => onWholeTextInput(state, host, identity, value),
            onSubmit: (value) => onWholeTextSubmit(state, host, identity, value),
          }),
        ],
      }),
    )
  }

  const n = commentCountOf(feedback)
  children.push(
    Box({
      key: `${key}:actions`,
      flexDirection: 'row',
      columnGap: 1,
      children: [
        Button({
          key: `${key}:whole-button`,
          label: 'whole draft',
          onPress: () => {
            openWholeInput(state, host, identity, `${key}:whole-input`).catch((error: unknown) => host.log(`focus failed: ${messageOf(error)}`))
          },
        }),
        Button({
          key: `${key}:approve`,
          label: 'Approve',
          onPress: () => {
            approve(state, host, draft).catch((error: unknown) => host.log(`submit failed: ${messageOf(error)}`))
          },
        }),
        Button({
          key: `${key}:submit`,
          label: 'Submit',
          onPress: () => {
            submit(state, host, draft).catch((error: unknown) => host.log(`submit failed: ${messageOf(error)}`))
          },
        }),
        Text({ dimColor: true, children: n === 1 ? '1 comment' : `${n} comments` }),
      ],
    }),
  )

  return Box({ key, flexDirection: 'column', rowGap: 1, children })
}

// Nothing here reads `state.host` beyond what the caller already resolved into `ui` and `host`:
// the render hook itself is the only place allowed to touch `$` (through `$.ui.resolve`), and
// this function draws from `state` alone, per the module's own rule against reading the
// transcript from `ui.render`. `bodyColumns` and `bodyRows` are the render input's own body
// size, passed down for the "no open drafts" line alone: centering it takes a Box as large as
// the body to center inside, and the size to make one is only ever in the render input, never
// in state.
function paneOf(ui: Ui, state: State, host: Host, bodyColumns: number, bodyRows: number): RenderElement {
  const { Box, Text } = ui
  const visible = visibleOf(state)
  if (visible.length === 0) {
    // A first frame may report 0 for either before the surface has measured the pane; centering
    // into a zero-sized Box would draw nothing, so this falls back to the plain line instead.
    if (bodyColumns <= 0 || bodyRows <= 0) return Text({ children: 'no open drafts' })
    return Box({
      key: 'empty',
      width: bodyColumns,
      height: bodyRows,
      justifyContent: 'center',
      alignItems: 'center',
      children: [Text({ dimColor: true, children: 'no open drafts' })],
    })
  }

  return Box({
    key: PANE_ID,
    flexDirection: 'column',
    rowGap: 1,
    children: visible.map((openDraft, index) => draftBoxOf(ui, index, openDraft, state, host)),
  })
}

// The diff a desktop `Changes` view shows: this draft's body against the body of the draft it
// revises. Null when there is nothing to compare. A file draft's earlier text is not in the
// transcript (the file has changed since), so a file draft on either side has no diff.
function revisionDiffOf(trail: readonly Draft[]): string | null {
  const draft = trail.at(-1)
  const earlier = trail.at(-2)
  if (draft === undefined || earlier === undefined || draft.file !== null || earlier.file !== null) return null
  return unifiedDiffOf(earlier.body, draft.body)
}

function setView(state: State, host: Host, identity: string, view: View): void {
  state.views.set(identity, view)
  host.invalidate()
}

// One open draft as desktop.ts takes it: the data to draw, and a closure for each control that
// calls the same transitions the terminal tree calls.
function desktopDraftModelOf(index: number, openDraft: OpenDraft, state: State, host: Host): DesktopDraft {
  const { draft, isDuplicate } = openDraft
  const identity = identityOf(draft)
  const feedback = feedbackOf(state, identity)
  const key = `d${index}`
  const trail = revisionTrailOf(draft, state.history)
  const diff = revisionDiffOf(trail)
  const stored = state.views.get(identity) ?? 'comment'
  // A `changes` view left over from an earlier parse falls back to `comment` when there is no
  // diff to show any more.
  const view: View = stored === 'changes' && diff === null ? 'comment' : stored
  const logged = (label: string) => (error: unknown) => host.log(`${label} failed: ${messageOf(error)}`)
  return {
    key,
    draft,
    isDuplicate,
    feedback,
    readError: state.readErrors.get(identity),
    view,
    trail,
    diff,
    fileHref: draft.file === null ? null : fileHrefOf(draft.file, state.cwd),
    segments: segmentsForDraft(draft, feedback),
    actions: {
      setView: (next) => setView(state, host, identity, next),
      removeSpan: (spanIndex) => onSpanRemove(state, host, identity, spanIndex),
      removeWhole: () => onWholeRemove(state, host, identity),
      openWhole: () => {
        openWholeInput(state, host, identity, `${key}:whole-input`).catch(logged('focus'))
      },
      spanInput: (text) => onSpanTextInput(state, host, identity, text),
      spanSubmit: (text) => onSpanTextSubmit(state, host, identity, text),
      wholeInput: (text) => onWholeTextInput(state, host, identity, text),
      wholeSubmit: (text) => onWholeTextSubmit(state, host, identity, text),
      approve: () => {
        approve(state, host, draft).catch(logged('submit'))
      },
      submit: () => {
        submit(state, host, draft).catch(logged('submit'))
      },
    },
  }
}

function desktopPaneOf(ui: DesktopUi, state: State, host: Host): RenderElement {
  const visible = visibleOf(state)
  if (visible.length === 0) return desktopEmptyOf(ui)
  return ui.Box({
    key: PANE_ID,
    flexDirection: 'column',
    rowGap: 1,
    children: visible.map((openDraft, index) => desktopDraftOf(ui, desktopDraftModelOf(index, openDraft, state, host))),
  })
}

export function register(on: On) {
  const state: State = {
    host: null,
    isOpen: false,
    wantsOpen: false,
    open: [],
    cwd: '',
    feedback: new Map(),
    sent: new Set(),
    isSubmitting: false,
    readErrors: new Map(),
    history: new Map(),
    views: new Map(),
  }

  on('session.start', async ($, e, next) => {
    state.host = hostOf($)
    state.cwd = e.cwd
    await state.host.register().catch((error: unknown) => {
      state.host?.log(`/${COMMAND} is not available: ${messageOf(error)}`)
    })
    const stored = await state.host.storeGet(STORE_KEY).catch(() => undefined)
    state.wantsOpen = stored === true
    // `reparse` runs first, so whether to open (there is a draft to show) is decided from this
    // session's own transcript, not just the flag; `openIfWanted` inside it is what actually
    // opens the pane, without focus, when that is warranted.
    await reparse(state)
    return next(e)
  })

  on('turn.complete', ($, e, next) => {
    void reparse(state)
    return next(e)
  })

  on('command.run', { command: COMMAND }, async ($, e, next) => {
    const host = state.host
    if (host === null) return next(e)

    if (state.isOpen) {
      await host.close()
      state.isOpen = false
      state.wantsOpen = false
      await host.storeSet(STORE_KEY, false)
      return { text: 'draft-pane hidden' }
    }

    // Opens even with zero drafts: the person asked outright, unlike the automatic open in
    // `openIfWanted`, which only ever opens where there is something to show.
    await host.open(true)
    state.isOpen = true
    state.wantsOpen = true
    await host.storeSet(STORE_KEY, true)
    await reparse(state)
    return { text: 'draft-pane shown' }
  })

  on('ui.close', { id: PANE_ID }, async ($, e, next) => {
    const result = await next(e)
    const host = state.host
    if (result.deny === undefined && host !== null) {
      state.isOpen = false
      state.wantsOpen = false
      await host.storeSet(STORE_KEY, false)
      updateStatus(state)
    }
    return result
  })

  // A draft-selection.ts Client posted this on a drag's release ('client' origin: code sent it,
  // on nobody's behalf, so `data` is input to validate, never a fact). Its `element` key is
  // `d${index}:seg${k}` (set in `draftBoxOf`): `index` addresses `visibleOf(state)` — the same
  // order the pane drew it in — and `k` addresses that draft's own segments, recomputed here from
  // its feedback with the same `segmentsForDraft` `draftBoxOf` drew from, so the two sides agree
  // on what segment `k` means. A posted range is local to that segment's own text; `toAbsolute`
  // is what turns it into the offsets `Feedback.selection` keeps.
  on('ui.message', { requestId: PANE_ID }, async ($, e, next) => {
    const host = state.host
    if (host === null) return next(e)
    const elementMatch = /^d(\d+):seg(\d+)$/.exec(e.element)
    if (elementMatch === null) return next(e)
    const openDraft = visibleOf(state)[Number(elementMatch[1])]
    if (openDraft === undefined) return next(e)
    const message = selectionMessageOf(e.data)
    if (message === null) return next(e)

    const identity = identityOf(openDraft.draft)
    const feedback = feedbackOf(state, identity)
    const segment = segmentsForDraft(openDraft.draft, feedback)[Number(elementMatch[2])]
    if (segment === undefined) return next(e)
    const absolute = message.type === 'selected' ? toAbsolute(segment, { start: message.start, end: message.end }) : null
    const selection = absolute === null ? null : withoutTrailingNewlinesOf(openDraft.draft.body, absolute)
    state.feedback.set(identity, withSelection(feedback, selection))
    host.invalidate()

    if (message.type === 'selected') {
      // `autoFocus` only places the ring once a site already holds the keyboard; a drag does
      // not give the pane the keyboard by itself. The open-with-focus request below is what
      // does: a mouse drag over the pane is the person's own act, so asking for the keyboard
      // right here, right after it, is the moment the surface grants the request (a pane opened
      // with `focus` gets it while the composer is empty). The `host.focus` call after that is
      // what then puts the ring on the comment `Input` itself.
      try {
        await host.open(true)
      } catch (error) {
        host.log(`focus: open failed: ${messageOf(error)}`)
      }
      await focusInput(host, `d${elementMatch[1]}:span-input`)
    }
    return next(e)
  })

  on('ui.render', { component: 'Pane' }, async ($, e, next) => {
    if (e.requestId !== PANE_ID || state.host === null) return next(e)
    if (e.surface === 'desktop') {
      const { Box, Button, Text, Input, Client, Svg, Markdown, Code } = await $.ui.resolve(e)
      return desktopPaneOf({ Box, Button, Text, Input, Client, Svg, Markdown, Code }, state, state.host)
    }
    if (e.surface !== 'terminal') return next(e)
    const { Box, Button, Text, Input, Client } = await $.ui.resolve(e)
    return paneOf({ Box, Button, Text, Input, Client }, state, state.host, e.props.bodyColumns, e.props.scroll.bodyRows)
  })
}

files.hooks/block.ts:
// Pure parsing and formatting for the ```draft block and the feedback lines a Submit press
// sends. No `$`, no hooks, no Claude Code runtime beyond the `SessionMessage` type: mod.ts is
// the only caller, and every export here is a plain function over strings and the transcript's
// own messages. Must not know about the pane's drawing, a drag, or how a span was chosen —
// only the block's text shape and the feedback line shape.

import type { SessionMessage } from 'claude-code'

// `file`, when not null, makes this a file draft: `body` is what mod.ts last read from that
// path (empty until the first read), not text carried in the block itself.
export type Draft = { number: number; title: string; body: string; file: string | null; revises: number | null }
export type OpenDraft = { draft: Draft; isDuplicate: boolean }
export type SpanComment = { start: number; end: number; comment: string }

export const FEEDBACK_HEADER_PREFIX = 'Feedback (draft-pane) on D'
export const APPROVED = '(approved)'
export const WHOLE_DRAFT = '(whole draft)'

// A block opens on three or more backticks followed by `draft`, and closes on a line of only
// backticks (at least as many as the opener) — so a four-backtick block can carry a three-
// backtick fence in its body without that fence line closing it early.
const OPEN_RE = /^(`{3,})draft[ \t]*$/
const CLOSE_RE = /^(`+)[ \t]*$/
const HEADER_RE = /^D(\d+)(?:\s*\(revises D(\d+)\))?:\s*(.*)$/
// The line right after the header, trimmed: when it matches, the draft names a file instead of
// carrying its text.
const FILE_RE = /^file:\s*(.+)$/
// Same shape as `${FEEDBACK_HEADER_PREFIX}<number>:`, spelled out so the pattern is visible
// in one place rather than built from the constant at runtime.
const FEEDBACK_LINE_RE = /^Feedback \(draft-pane\) on D(\d+):$/

// Leading and trailing blank lines (empty or whitespace only) dropped, an inner blank line
// kept — the body is the exact string the pane draws and the formatter slices, so nothing
// else here may change its length.
function trimBlankLines(lines: readonly string[]): string[] {
  const isBlank = (line: string): boolean => line.trim() === ''
  let start = 0
  let end = lines.length
  while (start < end && isBlank(lines[start] ?? '')) start += 1
  while (end > start && isBlank(lines[end - 1] ?? '')) end -= 1
  return lines.slice(start, end)
}

// A body's leading and trailing blank lines removed, an inner blank line kept — the same trim
// `draftOf` applies to a block's own body, exported so mod.ts applies it to a file's text too:
// a file draft's body must be trimmed the same way, or its identity would depend on which of the
// two places did the trimming.
export function trimmedBodyOf(text: string): string {
  return trimBlankLines(text.split('\n')).join('\n')
}

// `blockLines` is everything between the opener and the closer (or end of text), header line
// first. A missing or malformed header drops the block rather than failing the whole parse: a
// model's draft can contain a stray block. A plain draft whose body trims away to nothing is
// dropped too, but a file draft is kept with an empty body — mod.ts fills it in on the first
// read, and there is no text here yet to judge empty.
function draftOf(blockLines: readonly string[]): Draft | null {
  const headerLine = blockLines[0]
  if (headerLine === undefined) return null
  const headerMatch = HEADER_RE.exec(headerLine)
  if (headerMatch === null) return null
  const number = Number(headerMatch[1] ?? '')
  const revisesGroup = headerMatch[2]
  const revises = revisesGroup === undefined ? null : Number(revisesGroup)
  const title = (headerMatch[3] ?? '').trim()

  const fileLine = blockLines[1]
  const fileMatch = fileLine === undefined ? null : FILE_RE.exec(fileLine.trim())
  if (fileMatch !== null) {
    const file = (fileMatch[1] ?? '').trim()
    return { number, title, body: '', file, revises }
  }

  const body = trimmedBodyOf(blockLines.slice(1).join('\n'))
  if (body === '') return null
  return { number, title, body, file: null, revises }
}

// Every draft from every ```draft block in `text` (a message may carry more than one), in
// order. Text outside a block is ignored; an unclosed block runs to the end of the text.
export function draftsOf(text: string): Draft[] {
  const drafts: Draft[] = []
  const lines = text.split('\n')
  let i = 0
  while (i < lines.length) {
    const openMatch = OPEN_RE.exec(lines[i] ?? '')
    if (openMatch === null) {
      i += 1
      continue
    }
    const fenceLength = (openMatch[1] ?? '').length
    i += 1
    const blockLines: string[] = []
    while (i < lines.length) {
      const closeMatch = CLOSE_RE.exec(lines[i] ?? '')
      if (closeMatch !== null && (closeMatch[1] ?? '').length >= fenceLength) {
        i += 1
        break
      }
      blockLines.push(lines[i] ?? '')
      i += 1
    }
    const draft = draftOf(blockLines)
    if (draft !== null) drafts.push(draft)
  }
  return drafts
}

export function identityOf(draft: Draft): string {
  return `${draft.number}\n${draft.title}\n${draft.body}`
}

export function headerOf(draft: Draft): string {
  return `${FEEDBACK_HEADER_PREFIX}${draft.number}:`
}

// Every `Feedback (draft-pane) on D<n>:` line in `text`, as numbers, in order.
export function feedbackNumbersOf(text: string): number[] {
  const numbers: number[] = []
  for (const line of text.split('\n')) {
    const match = FEEDBACK_LINE_RE.exec(line.trim())
    if (match !== null) numbers.push(Number(match[1] ?? ''))
  }
  return numbers
}

// Every draft with an open number, deduplicated by identity (first occurrence kept), sorted by
// number ascending.
//
// Only the last assistant message that holds a ```draft block supplies candidates. Without that
// rule a draft the person never answered — an older topic, or one answered in plain words
// instead of from the pane — would stay open forever, next to whatever the model just wrote. An
// older draft is still readable in the transcript, and the model can post it again under a new
// number.
//
// Feedback numbers are still read from every non-assistant message: a feedback prompt for the
// newest draft can sit after the message that named it. `revised` is still built from every
// draft in every assistant message, not only the newest one's, since the newest message may
// itself carry both a draft and the revision that replaces it.
export function openDraftsOf(messages: readonly SessionMessage[]): OpenDraft[] {
  const allDrafts: Draft[] = []
  const feedbackNumbers: number[] = []
  let newestDrafts: Draft[] = []
  for (const message of messages) {
    if (message.role === 'assistant') {
      const drafts = draftsOf(message.text)
      allDrafts.push(...drafts)
      if (drafts.length > 0) newestDrafts = drafts
    } else {
      feedbackNumbers.push(...feedbackNumbersOf(message.text))
    }
  }

  const feedbackSet = new Set(feedbackNumbers)
  const revised = new Set<number>()
  for (const draft of allDrafts) {
    if (draft.revises !== null) revised.add(draft.revises)
  }

  const isOpen = (draft: Draft): boolean => !feedbackSet.has(draft.number) && !revised.has(draft.number)

  const seen = new Set<string>()
  const open: Draft[] = []
  for (const draft of newestDrafts) {
    if (!isOpen(draft)) continue
    const identity = identityOf(draft)
    if (seen.has(identity)) continue
    seen.add(identity)
    open.push(draft)
  }

  const identitiesByNumber = new Map<number, Set<string>>()
  for (const draft of open) {
    const identities = identitiesByNumber.get(draft.number) ?? new Set<string>()
    identities.add(identityOf(draft))
    identitiesByNumber.set(draft.number, identities)
  }

  return open
    .map((draft) => ({
      draft,
      isDuplicate: (identitiesByNumber.get(draft.number)?.size ?? 0) > 1,
    }))
    .sort((a, b) => a.draft.number - b.draft.number)
}

export function quoteOf(text: string): string {
  return text
    .split('\n')
    .map((line) => '> ' + line)
    .join('\n')
}

// A file draft's second line names the file the quotes came from, so the prompt is
// self-contained without the model going back to the block.
function fileLineOf(draft: Draft): string | null {
  return draft.file === null ? null : `file: ${draft.file}`
}

// The prompt a Submit press sends: the header, then for a file draft the `file:` line, then for
// each span (in ascending `start` order, stable, regardless of the order given) the quoted slice
// of `draft.body` and the comment on its own line, then, when `whole` is given, one
// `(whole draft) <comment>` line.
export function feedbackTextOf(draft: Draft, spans: readonly SpanComment[], whole: string | null): string {
  const ordered = [...spans].sort((a, b) => a.start - b.start)
  const fileLine = fileLineOf(draft)
  const lines: string[] = [headerOf(draft), ...(fileLine === null ? [] : [fileLine])]
  for (const span of ordered) {
    lines.push(quoteOf(draft.body.slice(span.start, span.end)))
    lines.push(span.comment)
  }
  if (whole !== null) lines.push(`${WHOLE_DRAFT} ${whole}`)
  return lines.join('\n')
}

export function approvalTextOf(draft: Draft): string {
  const fileLine = fileLineOf(draft)
  return [headerOf(draft), ...(fileLine === null ? [] : [fileLine]), APPROVED].join('\n')
}

// Every draft in every assistant message, by number. When a number occurs more than once, the
// latest occurrence wins: the pane uses this map only to find what a revision replaced, and the
// newest text under a number is the text the person last saw under it.
export function draftsByNumberOf(messages: readonly SessionMessage[]): Map<number, Draft> {
  const byNumber = new Map<number, Draft>()
  for (const message of messages) {
    if (message.role !== 'assistant') continue
    for (const draft of draftsOf(message.text)) byNumber.set(draft.number, draft)
  }
  return byNumber
}

// The chain of drafts that `draft` revises, oldest first, with `draft` itself last. The walk
// stops at a number the map does not have, and at a number it already visited, so a model that
// writes a loop of `revises` lines cannot make it run forever.
export function revisionTrailOf(draft: Draft, byNumber: ReadonlyMap<number, Draft>): Draft[] {
  const trail: Draft[] = [draft]
  const seen = new Set<number>([draft.number])
  let revises = draft.revises
  while (revises !== null && !seen.has(revises)) {
    const earlier = byNumber.get(revises)
    if (earlier === undefined) break
    trail.unshift(earlier)
    seen.add(revises)
    revises = earlier.revises
  }
  return trail
}

files.hooks/feedback.ts:
// Pure state for one draft's pending feedback: the span just dragged and not yet commented on,
// the committed span comments, and the one committed whole-draft comment. No `$`, no hooks —
// mod.ts is the only caller, and every export here is a plain function over a `Feedback` value.
// Must not know about how a drag is drawn (draft-selection.ts) or how a draft's body is parsed
// or how a feedback prompt is written (block.ts) — only this pane's own pending state.

import type { SpanComment } from './block'
import type { SelectionMessage } from './draft-selection'

export type Selection = { start: number; end: number }

// `spanText` and `wholeText` mirror what their `Input` holds. Every redraw hands the `Input`
// its `value` again (the engine has no state of its own for it), so without a mirror here a
// redraw triggered by a finished turn or a fresh drag on another draft would hand the `Input`
// back an empty string and silently erase what the person had already typed.
export type Feedback = {
  selection: Selection | null
  spanText: string
  spans: SpanComment[]
  whole: string | null
  wholeText: string
  // True while the whole-draft `Input` is on screen: drawn on a `whole draft` button press, and
  // closed again on Enter (empty or not). Kept false the rest of the time so the pane holds no
  // `Input` until the person asks for one — see mod.ts's own note on why.
  wholeOpen: boolean
}

export const EMPTY_FEEDBACK: Feedback = { selection: null, spanText: '', spans: [], whole: null, wholeText: '', wholeOpen: false }

export function withSelection(feedback: Feedback, selection: Selection | null): Feedback {
  return { ...feedback, selection, spanText: '' }
}

export function withSpanText(feedback: Feedback, text: string): Feedback {
  return { ...feedback, spanText: text }
}

// No selection: nothing to attach the comment to, so the commit is a no-op. An empty Enter
// (only whitespace) is how the person cancels a drag — it drops the selection and adds nothing,
// rather than committing a blank comment.
export function withSpanCommitted(feedback: Feedback, text: string): Feedback {
  const selection = feedback.selection
  if (selection === null) return feedback
  const trimmed = text.trim()
  if (trimmed === '') return { ...feedback, selection: null, spanText: '' }
  return {
    ...feedback,
    selection: null,
    spanText: '',
    spans: [...feedback.spans, { start: selection.start, end: selection.end, comment: trimmed }],
  }
}

export function withSpanRemoved(feedback: Feedback, index: number): Feedback {
  if (index < 0 || index >= feedback.spans.length) return feedback
  return { ...feedback, spans: [...feedback.spans.slice(0, index), ...feedback.spans.slice(index + 1)] }
}

export function withWholeText(feedback: Feedback, text: string): Feedback {
  return { ...feedback, wholeText: text }
}

export function withWholeOpen(feedback: Feedback, open: boolean): Feedback {
  return { ...feedback, wholeOpen: open }
}

// `whole` holds at most one comment: a second Enter replaces the first rather than adding a
// second. An empty Enter removes it. Enter always closes the field, sent or not, so the `Input`
// never lingers once the person has said what they meant to say.
export function withWholeCommitted(feedback: Feedback, text: string): Feedback {
  const trimmed = text.trim()
  return { ...feedback, whole: trimmed === '' ? null : trimmed, wholeText: '', wholeOpen: false }
}

export function withWholeRemoved(feedback: Feedback): Feedback {
  return { ...feedback, whole: null }
}

export function commentCountOf(feedback: Feedback): number {
  return feedback.spans.length + (feedback.whole === null ? 0 : 1)
}

// True while an Input holds text Enter has not yet turned into a span or whole-draft comment —
// the case a Submit or Approve press must refuse, or that text would be lost with no word said.
export function hasUnsentTextOf(feedback: Feedback): boolean {
  return feedback.spanText.trim() !== '' || feedback.wholeText.trim() !== ''
}

// `data` came from a draft-selection.ts Client's post — code sent it, not the engine — so this
// is the one place that message is checked before mod.ts trusts its shape.
export function selectionMessageOf(data: unknown): SelectionMessage | null {
  if (typeof data !== 'object' || data === null) return null
  const type = Reflect.get(data, 'type')
  if (type === 'cleared') return { type: 'cleared' }
  if (type !== 'selected') return null
  const start = Reflect.get(data, 'start')
  const end = Reflect.get(data, 'end')
  if (typeof start !== 'number' || typeof end !== 'number' || start < 0 || end < start) return null
  return { type: 'selected', start, end }
}

// A release at column 0 of the next line posts an `end` right after the `\n` it dragged past —
// the person meant the line above, not the break itself. Left as is, that `\n` would become the
// span's own anchor line (segments.ts's `anchorLineOf` reads `end - 1`) and the quote's last
// line, so the highlight and the quote both want the words only, never the break that follows
// them. Stops at one character so a selection that is itself a single `\n` is left alone, rather
// than shrunk to an empty range nothing can anchor to.
export function withoutTrailingNewlinesOf(body: string, range: Selection): Selection {
  let end = range.end
  while (end > range.start + 1 && body[end - 1] === '\n') end -= 1
  return end === range.end ? range : { ...range, end }
}

// The quote line drawn above a span's Input and the first column of a comment row: the slice
// collapsed to one line (a dragged span can cross a newline) and cut short so a long quote does
// not crowd out the comment beside it.
export function shortQuoteOf(body: string, selection: Selection, maxLength = 40): string {
  const collapsed = body.slice(selection.start, selection.end).replace(/\s+/g, ' ').trim()
  if (collapsed.length <= maxLength) return collapsed
  return `${collapsed.slice(0, maxLength)}…`
}

files.hooks/segments.ts:
// Pure geometry for splitting a draft's body into segments — one per line that already carries a
// comment (its anchor line), plus the rest after the last one — so mod.ts can draw one `Client`
// per segment and place that segment's comments right under it. No `$`, no drawing, no
// `Feedback` value: this file knows only lines, character offsets and anchor line numbers, never
// a comment's text or how a segment ends up on screen.

import { absoluteOffsetOf, posOf } from './draft-selection'

export type Segment = { index: number; firstLine: number; lastLine: number; baseOffset: number; lines: string[] }

// The line a comment sits on: the line holding the last character of its span, `end - 1`, never
// below `start` (an empty span still anchors to the line it starts on).
export function anchorLineOf(lines: readonly string[], span: { start: number; end: number }): number {
  return posOf(lines, Math.max(span.start, span.end - 1)).line
}

// `lines` split into segments at each anchor: segment `k` holds the lines after the previous
// anchor up to and including anchor `k`, in ascending order with duplicates dropped; a final
// segment holds whatever is left after the last anchor, omitted when that is nothing (the last
// line was itself an anchor).
export function segmentsOf(lines: readonly string[], anchorLines: readonly number[]): Segment[] {
  const maxLine = Math.max(lines.length - 1, 0)
  const clamped = anchorLines.map((line) => Math.min(Math.max(line, 0), maxLine))
  const sortedAnchors = [...new Set(clamped)].sort((a, b) => a - b)

  const segments: Segment[] = []
  let firstLine = 0
  for (const anchor of sortedAnchors) {
    segments.push({
      index: segments.length,
      firstLine,
      lastLine: anchor,
      baseOffset: absoluteOffsetOf(lines, { line: firstLine, col: 0 }),
      lines: lines.slice(firstLine, anchor + 1),
    })
    firstLine = anchor + 1
  }
  if (firstLine <= maxLine) {
    segments.push({
      index: segments.length,
      firstLine,
      lastLine: maxLine,
      baseOffset: absoluteOffsetOf(lines, { line: firstLine, col: 0 }),
      lines: lines.slice(firstLine, maxLine + 1),
    })
  }
  return segments
}

// `range`, given as offsets local to `segment`'s own text, converted to offsets into the whole
// body — the shape `SpanComment` and `Feedback.selection` keep.
export function toAbsolute(segment: Segment, range: { start: number; end: number }): { start: number; end: number } {
  return { start: segment.baseOffset + range.start, end: segment.baseOffset + range.end }
}

// The inverse of `toAbsolute`, or `null` when `range` (offsets into the whole body) does not lie
// inside `segment`'s own text — the case a `Client` outside the one the person dragged in must
// draw no highlight at all.
export function toLocal(segment: Segment, range: { start: number; end: number }): { start: number; end: number } | null {
  const start = range.start - segment.baseOffset
  const end = range.end - segment.baseOffset
  const textLength = segment.lines.join('\n').length
  if (start < 0 || end > textLength) return null
  return { start, end }
}

files.hooks/desktop.ts:
// The pane's tree on Claude Code Desktop. The terminal keeps the tree that mod.ts draws; the
// desktop has more elements (`Svg`, `Markdown`, `Code`, native buttons, borders that a hover can
// color), and this file uses them: each draft is a card with a header, a revision trail, a map of
// where the comments fall, and three views of the body — `Comment` (the drag-to-comment text the
// terminal also has), `Preview` (the body drawn as markdown, or a file draft's code with syntax
// colors), and `Changes` (a diff against the draft that this one revises).
//
// Must NOT know about: `$`, the transcript, or how a press changes state. mod.ts gives each draft
// as a `DesktopDraft` value, its segments already cut and its diff already computed, and the
// closures that a press or an input calls. The keys of the `Client`s, of the comment inputs and
// of the `Approve` and `Submit` buttons are the same as on the terminal, so mod.ts's `ui.message`
// handler and its focus calls need no second case.

import type { Elements, RenderElement } from 'claude-code'
import type { Draft } from './block'
import { diffStatOf } from './diff'
import type { Feedback } from './feedback'
import { commentCountOf, shortQuoteOf } from './feedback'
import type { Segment } from './segments'
import { anchorLineOf, toLocal } from './segments'
import { commentMapSvgOf, emptySheetSvgOf, revisionTrailSvgOf } from './svg'

export type DesktopUi = Pick<Elements['desktop'], 'Box' | 'Button' | 'Text' | 'Input' | 'Client' | 'Svg' | 'Markdown' | 'Code'>

export type View = 'comment' | 'preview' | 'changes'

export type DraftActions = {
  setView: (view: View) => void
  removeSpan: (index: number) => void
  removeWhole: () => void
  openWhole: () => void
  spanInput: (text: string) => void
  spanSubmit: (text: string) => void
  wholeInput: (text: string) => void
  wholeSubmit: (text: string) => void
  approve: () => void
  submit: () => void
}

export type DesktopDraft = {
  key: string
  draft: Draft
  isDuplicate: boolean
  feedback: Feedback
  readError: string | undefined
  view: View
  // The drafts this one revises, oldest first, this one last (block.ts's `revisionTrailOf`).
  trail: readonly Draft[]
  // The diff against the draft this one revises, or null when there is no earlier text to
  // compare: no `revises`, the earlier draft is not in the transcript, or either one is a file
  // draft (the transcript does not keep a file's earlier text).
  diff: string | null
  // The `file:` link for a file draft's path, or null.
  fileHref: string | null
  segments: readonly Segment[]
  actions: DraftActions
}

// `Markdown` and `Code` take at most 10000 characters. A longer body is cut at a line break
// before that limit, and a dim line under it says so.
const MAX_SOURCE = 9000

function cutOf(text: string): { text: string; isCut: boolean } {
  if (text.length <= MAX_SOURCE) return { text, isCut: false }
  const at = text.lastIndexOf('\n', MAX_SOURCE)
  return { text: text.slice(0, at > 0 ? at : MAX_SOURCE), isCut: true }
}

// The `file:` URL of a draft's path, made absolute against the session's working directory.
// Null for a path that does not become absolute (a Windows path, or no working directory), since
// a `file:` link must name an absolute path.
export function fileHrefOf(path: string, cwd: string): string | null {
  const absolute = path.startsWith('/') ? path : cwd.startsWith('/') ? `${cwd.replace(/\/+$/, '')}/${path}` : null
  if (absolute === null) return null
  return `file://${encodeURI(absolute)}`
}

// Plain drafts and markdown or text files show as markdown; any other file shows as code, with
// the language that `Code` infers from the path.
export function previewKindOf(draft: Draft): 'markdown' | 'code' {
  if (draft.file === null) return 'markdown'
  return /\.(md|markdown|mdx|txt)$/i.test(draft.file) ? 'markdown' : 'code'
}

export function statsOf(body: string): string {
  const lines = body === '' ? 0 : body.split('\n').length
  const words = body.split(/\s+/).filter((word) => word !== '').length
  return `${lines} ${lines === 1 ? 'line' : 'lines'} · ${words} ${words === 1 ? 'word' : 'words'} · ${body.length} chars`
}

function headerOf(ui: DesktopUi, d: DesktopDraft): RenderElement {
  const { Box, Text } = ui
  const { draft } = d
  return Box({
    key: `${d.key}:header`,
    flexDirection: 'row',
    justifyContent: 'space-between',
    columnGap: 2,
    flexWrap: 'wrap',
    children: [
      Box({
        flexDirection: 'row',
        columnGap: 1,
        children: [Text({ inverse: true, bold: true, children: ` D${draft.number} ` }), Text({ bold: true, children: draft.title })],
      }),
      Text({ dimColor: true, children: statsOf(draft.body) }),
    ],
  })
}

function trailOf(ui: DesktopUi, d: DesktopDraft): RenderElement | null {
  if (d.trail.length < 2) return null
  const { Box, Svg, Text } = ui
  const earlier = d.trail.at(-2) as Draft
  return Box({
    key: `${d.key}:trail`,
    flexDirection: 'row',
    columnGap: 1,
    alignItems: 'center',
    children: [
      Svg({
        source: revisionTrailSvgOf(d.trail.map(({ number, title }) => ({ number, title }))),
        alt: `Revisions: ${d.trail.map((draft) => `D${draft.number}`).join(', ')}`,
        isInteractive: true,
      }),
      Text({ dimColor: true, children: `revises D${earlier.number}` }),
    ],
  })
}

function tabsOf(ui: DesktopUi, d: DesktopDraft): RenderElement {
  const { Box, Button } = ui
  const tab = (view: View, label: string): RenderElement =>
    Button({ key: `${d.key}:view:${view}`, label, ...(d.view === view ? {} : { dimColor: true }), onPress: () => d.actions.setView(view) })
  const tabs = [tab('comment', 'Comment'), tab('preview', 'Preview')]
  if (d.diff !== null) {
    const { added, removed } = diffStatOf(d.diff)
    const earlier = d.trail.at(-2)
    tabs.push(tab('changes', `Changes from D${earlier?.number ?? '?'}  +${added} −${removed}`))
  }
  return Box({ key: `${d.key}:tabs`, flexDirection: 'row', columnGap: 1, children: tabs })
}

function commentMapOf(ui: DesktopUi, d: DesktopDraft): RenderElement | null {
  const { feedback, draft } = d
  if (feedback.spans.length === 0 && feedback.selection === null) return null
  const { Svg } = ui
  const marks = feedback.spans.map((span) => ({ start: span.start, end: span.end, tip: `“${shortQuoteOf(draft.body, span)}” ${span.comment}` }))
  const pending = feedback.selection === null ? null : { ...feedback.selection, tip: `“${shortQuoteOf(draft.body, feedback.selection)}” (no comment yet)` }
  const n = marks.length
  return Svg({
    source: commentMapSvgOf(draft.body.length, marks, pending),
    alt: `Where the ${n} ${n === 1 ? 'comment falls' : 'comments fall'} in the draft`,
    isInteractive: true,
  })
}

function commentCardOf(ui: DesktopUi, key: string, quote: string, comment: string, removeKey: string, onRemove: () => void): RenderElement {
  const { Box, Button, Text } = ui
  return Box({
    key,
    flexDirection: 'column',
    borderStyle: 'round',
    borderDimColor: true,
    hover: { borderColor: 'cyan' },
    paddingX: 1,
    children: [
      Box({
        flexDirection: 'row',
        justifyContent: 'space-between',
        columnGap: 1,
        children: [Text({ italic: true, dimColor: true, children: quote }), Button({ key: removeKey, label: 'Remove', dimColor: true, onPress: onRemove })],
      }),
      Text({ children: comment }),
    ],
  })
}

function spanCardOf(ui: DesktopUi, d: DesktopDraft, spanIndex: number): RenderElement {
  const span = d.feedback.spans[spanIndex] as Feedback['spans'][number]
  return commentCardOf(ui, `${d.key}:c${spanIndex}`, `“${shortQuoteOf(d.draft.body, span)}”`, span.comment, `${d.key}:c${spanIndex}:remove`, () =>
    d.actions.removeSpan(spanIndex),
  )
}

// The span indexes of `feedback.spans` in reading order, each kept with its own index so a
// card's `Remove` still removes the span it shows.
function spanOrderOf(feedback: Feedback): number[] {
  return feedback.spans
    .map((span, index) => ({ start: span.start, index }))
    .sort((a, b) => a.start - b.start)
    .map(({ index }) => index)
}

function pendingInputOf(ui: DesktopUi, d: DesktopDraft): RenderElement {
  const { Box, Text, Input } = ui
  const selection = d.feedback.selection as NonNullable<Feedback['selection']>
  return Box({
    key: `${d.key}:span-input-row`,
    flexDirection: 'column',
    borderStyle: 'round',
    borderColor: 'blue',
    paddingX: 1,
    children: [
      Text({ italic: true, dimColor: true, children: `“${shortQuoteOf(d.draft.body, selection)}”` }),
      Input({
        key: `${d.key}:span-input`,
        label: 'comment',
        placeholder: 'Enter adds it; empty Enter drops the span',
        value: d.feedback.spanText,
        autoFocus: true,
        onInput: (value) => d.actions.spanInput(value),
        onSubmit: (value) => d.actions.spanSubmit(value),
      }),
    ],
  })
}

// The `Comment` view: the same segments and `Client`s as the terminal, with each comment as a
// card right under the line that it ends on.
function commentViewOf(ui: DesktopUi, d: DesktopDraft): RenderElement[] {
  const { Box, Client, Text } = ui
  const lines = d.draft.body.split('\n')
  const order = spanOrderOf(d.feedback)
  const selection = d.feedback.selection
  const children: RenderElement[] = []
  if (commentCountOf(d.feedback) === 0 && selection === null) {
    children.push(Text({ dimColor: true, children: 'Drag over the text to comment on a span.' }))
  }
  d.segments.forEach((segment, k) => {
    const armedRange = selection === null ? null : toLocal(segment, selection)
    children.push(
      Client({
        key: `${d.key}:seg${k}`,
        // A string literal, not a constant: the validator reads a Client's `module` statically.
        module: './draft-selection.ts',
        props: { lines: segment.lines, ...(armedRange === null ? {} : { armedRange }) },
        width: '100%',
      }),
    )
    const rows: RenderElement[] = order
      .filter((index) => anchorLineOf(lines, d.feedback.spans[index] as Feedback['spans'][number]) === segment.lastLine)
      .map((index) => spanCardOf(ui, d, index))
    if (selection !== null && anchorLineOf(lines, selection) === segment.lastLine) rows.push(pendingInputOf(ui, d))
    children.push(Box({ key: `${d.key}:seg${k}:rows`, flexDirection: 'column', rowGap: 1, children: rows }))
  })
  return children
}

function cutNoteOf(ui: DesktopUi, isCut: boolean): RenderElement[] {
  return isCut ? [ui.Text({ dimColor: true, children: 'The rest is cut here. The Comment view shows all of it.' })] : []
}

// The `Preview` view: the body as the person will read it, then every committed comment as a
// card, so a comment stays in sight while the person reads.
function previewViewOf(ui: DesktopUi, d: DesktopDraft): RenderElement[] {
  const { Code, Markdown } = ui
  const { text, isCut } = cutOf(d.draft.body)
  const body =
    previewKindOf(d.draft) === 'markdown'
      ? Markdown({ key: `${d.key}:preview`, text })
      : Code({ source: text, startLine: 1, ...(d.draft.file === null ? {} : { path: d.draft.file }) })
  return [body, ...cutNoteOf(ui, isCut), ...spanOrderOf(d.feedback).map((index) => spanCardOf(ui, d, index))]
}

// The `Changes` view: what changed since the draft this one revises, as `diff -u` hunks.
function changesViewOf(ui: DesktopUi, d: DesktopDraft): RenderElement[] {
  const { Code, Text } = ui
  if (d.diff === null || d.diff === '') return [Text({ dimColor: true, children: 'No change in the text.' })]
  const { text, isCut } = cutOf(d.diff)
  return [Code({ source: text, format: 'diff' }), ...cutNoteOf(ui, isCut)]
}

function wholeOf(ui: DesktopUi, d: DesktopDraft): RenderElement[] {
  const { Box, Input } = ui
  const out: RenderElement[] = []
  const whole = d.feedback.whole
  if (whole !== null) {
    out.push(commentCardOf(ui, `${d.key}:whole`, 'Whole draft', whole, `${d.key}:whole:remove`, () => d.actions.removeWhole()))
  }
  if (d.feedback.wholeOpen) {
    out.push(
      Box({
        key: `${d.key}:whole-input-row`,
        borderStyle: 'round',
        borderColor: 'blue',
        paddingX: 1,
        children: [
          Input({
            key: `${d.key}:whole-input`,
            label: 'whole draft',
            placeholder: 'comment on the whole draft',
            value: d.feedback.wholeText,
            autoFocus: true,
            onInput: (value) => d.actions.wholeInput(value),
            onSubmit: (value) => d.actions.wholeSubmit(value),
          }),
        ],
      }),
    )
  }
  return out
}

function actionsOf(ui: DesktopUi, d: DesktopDraft): RenderElement {
  const { Box, Button, Text } = ui
  const n = commentCountOf(d.feedback)
  return Box({
    key: `${d.key}:actions`,
    flexDirection: 'row',
    columnGap: 1,
    alignItems: 'center',
    flexWrap: 'wrap',
    children: [
      Button({ key: `${d.key}:whole-button`, label: d.feedback.whole === null ? 'Comment on the whole draft' : 'Change the whole-draft comment', dimColor: true, onPress: () => d.actions.openWhole() }),
      Button({ key: `${d.key}:approve`, label: 'Approve', onPress: () => d.actions.approve() }),
      Button({ key: `${d.key}:submit`, label: n === 0 ? 'Submit' : `Submit ${n} ${n === 1 ? 'comment' : 'comments'}`, onPress: () => d.actions.submit() }),
      n === 0 ? Text({ dimColor: true, children: 'no comments yet' }) : Text({ color: 'green', children: 'ready to send' }),
    ],
  })
}

export function desktopDraftOf(ui: DesktopUi, d: DesktopDraft): RenderElement {
  const { Box, Markdown, Text } = ui
  const { draft } = d
  const children: RenderElement[] = [headerOf(ui, d)]
  if (d.isDuplicate) children.push(Text({ color: 'yellow', children: 'Another draft has the same number.' }))
  const trail = trailOf(ui, d)
  if (trail !== null) children.push(trail)

  const card = (): RenderElement =>
    Box({ key: d.key, flexDirection: 'column', rowGap: 1, borderStyle: 'round', borderColor: 'gray', paddingX: 1, children })

  if (draft.file !== null) {
    const name = draft.file.split('/').at(-1) ?? draft.file
    const label = name.replace(/[[\]\\]/g, '\\$&')
    children.push(Markdown({ text: d.fileHref === null ? `file: \`${draft.file}\`` : `file: [${label}](${d.fileHref}) \`${draft.file}\``, dimColor: true }))
    if (d.readError !== undefined) {
      children.push(Text({ color: 'red', children: `Cannot read the file: ${d.readError}` }))
      return card()
    }
    if (draft.body === '') {
      children.push(Text({ children: 'The file is empty.' }))
      return card()
    }
  }

  children.push(tabsOf(ui, d))
  const map = commentMapOf(ui, d)
  if (map !== null) children.push(map)

  if (d.view === 'preview') children.push(...previewViewOf(ui, d))
  else if (d.view === 'changes') children.push(...changesViewOf(ui, d))
  else children.push(...commentViewOf(ui, d))

  children.push(...wholeOf(ui, d), actionsOf(ui, d))
  return card()
}

export function desktopEmptyOf(ui: DesktopUi): RenderElement {
  const { Box, Markdown, Svg, Text } = ui
  return Box({
    key: 'empty',
    flexDirection: 'column',
    alignItems: 'center',
    rowGap: 1,
    paddingY: 2,
    children: [
      Svg({ source: emptySheetSvgOf(), alt: 'A blank sheet', width: 64, height: 64 }),
      Text({ bold: true, children: 'No open drafts' }),
      Markdown({ text: 'Ask for one with `/draft-pane:draft <what to draft>`. The newest draft opens here.', dimColor: true }),
    ],
  })
}

files.hooks/diff.ts:
// Pure line diff for the desktop pane's `Changes` view: the text of an earlier draft against the
// text of the draft that revises it, written as unified-diff hunks, the shape the desktop's
// `Code` element draws under `format: 'diff'`. No `$`, no drawing: mod.ts and desktop.ts are the
// only callers. Must not know what a draft is, or where the two texts came from.

type Op = { kind: ' ' | '-' | '+'; text: string; oldLine: number; newLine: number }

// Past this many cells, the longest-common-subsequence table costs too much for a draft pane.
// The diff then falls back to one hunk that removes every old line and adds every new one: still
// a correct diff, only a less precise one.
const MAX_TABLE_CELLS = 4_000_000

// The edit script from `before` to `after`, one entry per line, in order. Each entry keeps its
// 1-based line number in both texts (the number of the next line, for the side it is absent on),
// which is what a hunk header needs.
function opsOf(before: readonly string[], after: readonly string[]): Op[] {
  const n = before.length
  const m = after.length
  if (n * m > MAX_TABLE_CELLS) {
    return [
      ...before.map((text, i) => ({ kind: '-' as const, text, oldLine: i + 1, newLine: 1 })),
      ...after.map((text, j) => ({ kind: '+' as const, text, oldLine: n + 1, newLine: j + 1 })),
    ]
  }

  // lcs[i][j]: the length of the longest common subsequence of before[i..] and after[j..].
  const lcs: Uint32Array[] = Array.from({ length: n + 1 }, () => new Uint32Array(m + 1))
  for (let i = n - 1; i >= 0; i -= 1) {
    const row = lcs[i] as Uint32Array
    const below = lcs[i + 1] as Uint32Array
    for (let j = m - 1; j >= 0; j -= 1) {
      row[j] = before[i] === after[j] ? (below[j + 1] ?? 0) + 1 : Math.max(below[j] ?? 0, row[j + 1] ?? 0)
    }
  }

  const ops: Op[] = []
  let i = 0
  let j = 0
  while (i < n || j < m) {
    if (i < n && j < m && before[i] === after[j]) {
      ops.push({ kind: ' ', text: before[i] ?? '', oldLine: i + 1, newLine: j + 1 })
      i += 1
      j += 1
    } else if (i < n && (j === m || (lcs[i + 1]?.[j] ?? 0) >= (lcs[i]?.[j + 1] ?? 0))) {
      // A removal goes before the addition that replaces it, as `diff -u` writes them.
      ops.push({ kind: '-', text: before[i] ?? '', oldLine: i + 1, newLine: j + 1 })
      i += 1
    } else {
      ops.push({ kind: '+', text: after[j] ?? '', oldLine: i + 1, newLine: j + 1 })
      j += 1
    }
  }
  return ops
}

// The start and length of one side of a hunk header. A side with no lines names the line before
// the hunk, as `diff -u` does (`-0,0` for an insertion at the very top).
function rangeOf(start: number, length: number): string {
  return `${length === 0 ? start - 1 : start},${length}`
}

// `before` against `after` as unified-diff hunks with `context` unchanged lines around each
// change, or the empty string when the two texts are the same. Hunks closer than twice the
// context merge into one, as `diff -u` merges them.
export function unifiedDiffOf(before: string, after: string, context = 3): string {
  const ops = opsOf(before.split('\n'), after.split('\n'))
  const changed = ops.map((op, index) => (op.kind === ' ' ? -1 : index)).filter((index) => index >= 0)
  if (changed.length === 0) return ''

  const groups: { from: number; to: number }[] = []
  for (const index of changed) {
    const from = Math.max(0, index - context)
    const to = Math.min(ops.length - 1, index + context)
    const last = groups.at(-1)
    if (last !== undefined && from <= last.to + 1) {
      last.to = Math.max(last.to, to)
    } else {
      groups.push({ from, to })
    }
  }

  const out: string[] = []
  for (const { from, to } of groups) {
    const slice = ops.slice(from, to + 1)
    const first = slice[0] as Op
    const oldLength = slice.filter((op) => op.kind !== '+').length
    const newLength = slice.filter((op) => op.kind !== '-').length
    out.push(`@@ -${rangeOf(first.oldLine, oldLength)} +${rangeOf(first.newLine, newLength)} @@`)
    for (const op of slice) out.push(`${op.kind}${op.text}`)
  }
  return out.join('\n')
}

// How many lines the diff adds and removes, for the tab label and the header line.
export function diffStatOf(diff: string): { added: number; removed: number } {
  let added = 0
  let removed = 0
  for (const line of diff.split('\n')) {
    if (line.startsWith('@@')) continue
    if (line.startsWith('+')) added += 1
    else if (line.startsWith('-')) removed += 1
  }
  return { added, removed }
}

files.hooks/draft-selection.ts:
// A `Client` surface module (loaded by the engine from `mod.ts`'s `Client({ module:
// './draft-selection.ts' })`, never handed `$`): draws one draft's body (the hooks module
// passes `lines`) and turns a mouse drag over it into a character range, posted to the hooks
// module on release.
//
// This module draws the text itself, rather than overlaying a plain `Text` it stands in for, so
// it can highlight inside it — where a drag covers it, or where `armedRange` says the hooks
// module already armed. The highlighted `armedRange` is the span the person selected and has
// not yet commented on.
//
// Must NOT know about: what a draft is, or what the posted range is used for (arming a quote is
// the hooks module's job, driven by what this file posts through `surface.post`).

import type { ClientElements, ClientModule, ClientSurface, RenderElement } from 'claude-code'

export type DraftSelectionProps = {
  lines: readonly string[]
  // What the hooks module already armed from a past drag over this same text, as absolute
  // offsets (the same shape a 'selected' message posts) — undefined when nothing is armed here.
  // Drawn as a persistent highlight while no new drag is in progress, and a click landing
  // inside it, with no movement, is how the person drops it (see onPointerOf's 'up' handling).
  armedRange?: { start: number; end: number }
}

export type Pos = { line: number; col: number }
export type OrderedRange = { start: Pos; end: Pos }
export type SelectionMessage = { type: 'selected'; start: number; end: number } | { type: 'cleared' }

// One screen row: which logical line it comes from, where in that line it starts, and the
// characters it carries. A logical line the surface would otherwise soft-wrap is split into
// several of these by `visualRowsOf`, so the module (not the surface) decides where each screen
// row breaks — and a pointer's `y` can then index this list directly instead of `lines` itself.
export type VisualRow = { line: number; startCol: number; text: string }

type State = { anchor: Pos; current: Pos } | null

// A position from a pointer event, or from the drag's own memory, clamped onto real text: a
// line within `lines` (0 when there are none) and a column within that line (its length at
// most, so a click past the end of a short line still lands somewhere real).
export function clampPos(lines: readonly string[], pos: Pos): Pos {
  const line = Math.min(Math.max(pos.line, 0), Math.max(lines.length - 1, 0))
  const col = Math.min(Math.max(pos.col, 0), lines[line]?.length ?? 0)
  return { line, col }
}

function isBefore(a: Pos, b: Pos): boolean {
  return a.line < b.line || (a.line === b.line && a.col < b.col)
}

// The drag's two ends, clamped and put in reading order — a drag that moved up or left of
// where it started is still `start <= end`, so every other function here never sees a
// backwards range.
export function orderedRangeOf(lines: readonly string[], a: Pos, b: Pos): OrderedRange {
  const clampedA = clampPos(lines, a)
  const clampedB = clampPos(lines, b)
  return isBefore(clampedB, clampedA) ? { start: clampedB, end: clampedA } : { start: clampedA, end: clampedB }
}

// A range whose two ends landed on the same cell: a click, not a drag. Posted as `cleared`
// rather than an empty `selected`, so the hooks module never arms a zero-length quote.
export function isEmptyRange(range: OrderedRange): boolean {
  return range.start.line === range.end.line && range.start.col === range.end.col
}

// `pos` as a character offset into the text's lines joined by `\n` — the same shape `draft.body`
// already has, so the hooks module can slice it directly with no line math of its own.
export function absoluteOffsetOf(lines: readonly string[], pos: Pos): number {
  let offset = 0
  for (let i = 0; i < pos.line; i += 1) offset += (lines[i]?.length ?? 0) + 1
  return offset + pos.col
}

// The inverse of absoluteOffsetOf: an absolute character offset (as `armedRange` carries) back
// to a line and column, so a range the hooks module already armed can be drawn the same way a
// live drag is.
export function posOf(lines: readonly string[], offset: number): Pos {
  let remaining = offset
  for (let line = 0; line < lines.length; line += 1) {
    const length = lines[line]?.length ?? 0
    if (remaining <= length) return { line, col: remaining }
    remaining -= length + 1
  }
  return clampPos(lines, { line: Math.max(lines.length - 1, 0), col: remaining })
}

// The columns of one line a range covers, or null where the range does not reach that line:
// the whole line for one strictly between the range's ends, `[0, range.end.col)` or
// `[range.start.col, length)` for the line the range starts or ends on, both bounds on a
// single-line range.
export function selectedColumnsOf(range: OrderedRange, lineLength: number, lineIndex: number): { start: number; end: number } | null {
  if (lineIndex < range.start.line || lineIndex > range.end.line) return null
  const start = lineIndex === range.start.line ? range.start.col : 0
  const end = lineIndex === range.end.line ? range.end.col : lineLength
  return { start, end }
}

// The terminal cells one character occupies: 2 for the common CJK / fullwidth ranges (hiragana,
// katakana, kanji, Hangul, fullwidth Latin and punctuation), 1 otherwise. Not a complete Unicode
// East Asian Width table (an astral-plane character, a surrogate pair, still counts as two
// column-1 units here, same as every other index in this file already treats one) — this covers
// what broke: every column-counting function below treated one character as one cell, so a drag
// over Japanese text (each character 2 cells wide) landed on the wrong character entirely
// (measured, real-terminal feedback).
function cellWidthOf(code: number): number {
  const isWide =
    (code >= 0x1100 && code <= 0x115f) ||
    (code >= 0x2e80 && code <= 0xa4cf) ||
    (code >= 0xac00 && code <= 0xd7a3) ||
    (code >= 0xf900 && code <= 0xfaff) ||
    (code >= 0xff00 && code <= 0xff60) ||
    (code >= 0xffe0 && code <= 0xffe6)
  return isWide ? 2 : 1
}

function displayWidthOf(text: string): number {
  let width = 0
  for (let i = 0; i < text.length; i += 1) width += cellWidthOf(text.charCodeAt(i))
  return width
}

// The character index at or after `start` where `text`'s display width first reaches or would
// exceed `maxWidth` cells from `start` — the point a row of at most `maxWidth` columns has to
// end. Always advances past at least one character past `start`, so a single character wider
// than `maxWidth` on its own (a 2-cell character at the last column of a 1-column pane) still
// makes progress instead of looping forever; that one row ends up one cell over budget, the same
// trade the ASCII hard-break below already makes for a word wider than the whole pane.
function indexAtWidth(text: string, start: number, maxWidth: number): number {
  let width = 0
  for (let i = start; i < text.length; i += 1) {
    const w = cellWidthOf(text.charCodeAt(i))
    if (width + w > maxWidth && i > start) return i
    width += w
  }
  return text.length
}

// The character index in `text` whose cell span covers column `x` (0-based, clamped past the
// last character to `text.length`) — walks by display width, not character count, so a pointer
// past a 2-cell character lands after it, not one character short.
function charIndexAtColumn(text: string, x: number): number {
  let col = 0
  for (let i = 0; i < text.length; i += 1) {
    const w = cellWidthOf(text.charCodeAt(i))
    if (x < col + w) return i
    col += w
  }
  return text.length
}

// One logical line, greedily word-wrapped to `columns` cells (measured by display width, not
// character count): a break lands on the last space at or before the limit, and a single word
// wider than `columns` hard-breaks by character (the only way to keep every row within the
// width at all). `startCol` is the real index into the logical line — not reconstructed later by
// re-joining words — so a wrapped word's own text still slices correctly out of the original
// line.
function wrapLineOf(text: string, columns: number): { startCol: number; text: string }[] {
  if (!Number.isFinite(columns) || columns <= 0 || displayWidthOf(text) <= columns) return [{ startCol: 0, text }]
  const rows: { startCol: number; text: string }[] = []
  let rowStart = 0
  while (rowStart < text.length) {
    const limit = indexAtWidth(text, rowStart, columns)
    if (limit >= text.length) {
      rows.push({ startCol: rowStart, text: text.slice(rowStart, limit) })
      break
    }
    let breakAt = -1
    for (let i = limit; i > rowStart; i -= 1) {
      if (text[i] === ' ') {
        breakAt = i
        break
      }
    }
    if (breakAt === -1) {
      rows.push({ startCol: rowStart, text: text.slice(rowStart, limit) })
      rowStart = limit
    } else {
      rows.push({ startCol: rowStart, text: text.slice(rowStart, breakAt) })
      rowStart = breakAt + 1
    }
  }
  return rows
}

// Every logical line wrapped to `columns` cells, in order. `columns` is the surface's own
// `columns` (0 before its first layout); passed on as `Infinity` for that one frame, which
// wraps nothing and lets the surface soft-wrap on its own, same as before this file drew its
// own rows — the real width arrives on the next call and this takes over from there.
export function visualRowsOf(lines: readonly string[], columns: number): VisualRow[] {
  const rows: VisualRow[] = []
  lines.forEach((line, index) => {
    for (const row of wrapLineOf(line, columns)) rows.push({ line: index, startCol: row.startCol, text: row.text })
  })
  return rows
}

// A pointer event's cell, as a position in the logical text: `event.y` indexes `visualRows`
// directly (each is exactly one screen row, by construction), and `event.x` lands within that
// row's own slice of its logical line, offset by where the row starts. `charIndexAtColumn` (not
// a plain clamp of `x` itself) is what makes this correct for a row containing any 2-cell
// character: `x` is a terminal column, not a character index, and the two only coincide when
// every character on the row is 1 cell wide.
function screenPosOf(visualRows: readonly VisualRow[], event: { x: number; y: number }): Pos {
  const rowIndex = Math.min(Math.max(event.y, 0), Math.max(visualRows.length - 1, 0))
  const row = visualRows[rowIndex]
  if (row === undefined) return { line: 0, col: 0 }
  const col = charIndexAtColumn(row.text, Math.max(event.x, 0))
  return { line: row.line, col: row.startCol + col }
}

// The range a drag covers on one screen row, or null where the row is not covered at all: the
// same logical-line span `selectedColumnsOf` reports, intersected with the row's own
// `[startCol, startCol + text.length)` slice and rebased to that row's local columns.
function rowSelectionOf(range: OrderedRange, row: VisualRow, lineLength: number): { start: number; end: number } | null {
  const cols = selectedColumnsOf(range, lineLength, row.line)
  if (cols === null) return null
  const start = Math.max(cols.start, row.startCol)
  const end = Math.min(cols.end, row.startCol + row.text.length)
  if (start > end) return null
  return { start: start - row.startCol, end: end - row.startCol }
}

// One row: plain text, or split into an unhighlighted prefix, an inverse-video run for the
// covered part, and an unhighlighted suffix. A zero-width `columns` on a non-empty row (the
// cell right after 'down', before any 'move') draws as plain text — inserting a one-space
// highlighted run there, as a real (non-empty) selection does, turned the clicked character
// into a false blank (measured: real-terminal feedback). A zero-width `columns` on a genuinely
// empty row (one a multi-line drag covers in full) still draws as one highlighted space, so a
// blank line inside a real selection still shows as covered. No `wrap` prop: every row already
// fits `columns` by construction (visualRowsOf), so there is nothing left to cut or wrap.
function lineRowOf(elements: ClientElements, key: string, text: string, columns: { start: number; end: number } | null): RenderElement {
  const { Box, Text } = elements
  const isFalseBlank = columns !== null && columns.start === columns.end && text !== ''
  if (columns === null || isFalseBlank) {
    return Box({ key, children: [Text({ children: text === '' ? ' ' : text })] })
  }
  const before = text.slice(0, columns.start)
  const selected = text.slice(columns.start, columns.end)
  const after = text.slice(columns.end)
  const children: RenderElement[] = []
  if (before !== '') children.push(Text({ children: before }))
  children.push(Text({ inverse: true, children: selected === '' ? ' ' : selected }))
  if (after !== '') children.push(Text({ children: after }))
  return Box({ key, flexDirection: 'row', children })
}

// The pointer handler: 'down' starts a drag at the cell under the pointer, 'move' extends it
// (ignored before a 'down' started one — a hover with no button held), 'up' posts what the drag
// covered and ends it. A drag that never moved (a plain click) posts `cleared` whenever
// something is armed here, anywhere in this text — not only a click landing inside the
// highlight — since a click outside it dropping nothing read as unnatural (real-terminal
// feedback: clicking away from a selection is how clearing one usually works). Registered fresh
// on every call, which is how each render's `state` reaches the closure without a stale one
// from an earlier call.
function onPointerOf(
  lines: readonly string[],
  visualRows: readonly VisualRow[],
  state: State,
  armedRange: { start: number; end: number } | undefined,
  setState: (next: State) => void,
  post: (data: SelectionMessage) => void,
) {
  return (event: { type: string; x: number; y: number }) => {
    if (event.type === 'down') {
      const pos = screenPosOf(visualRows, event)
      setState({ anchor: pos, current: pos })
      return
    }
    if (event.type === 'move') {
      if (state === null) return
      const pos = screenPosOf(visualRows, event)
      setState({ anchor: state.anchor, current: pos })
      return
    }
    if (event.type === 'up') {
      if (state === null) return
      // The 'up' event carries its own cell, same as 'down' and 'move' do — read it directly
      // rather than trusting a 'move' to have landed there first. A drag with no 'move' in
      // between (a fast release, or a terminal that only sends 'move' on real movement) would
      // otherwise end up comparing the anchor to itself and reporting an empty range.
      const pos = screenPosOf(visualRows, event)
      const range = orderedRangeOf(lines, state.anchor, pos)
      if (isEmptyRange(range)) {
        if (armedRange !== undefined) post({ type: 'cleared' })
      } else {
        post({ type: 'selected', start: absoluteOffsetOf(lines, range.start), end: absoluteOffsetOf(lines, range.end) })
      }
      setState(null)
    }
  }
}

// `surface` is the real `ClientSurface` from the engine, or (in a test) any object shaped
// like one — the module never reaches for anything else on it.
export function drawDraftSelection(
  props: DraftSelectionProps,
  surface: Pick<ClientSurface<State>, 'elements' | 'state' | 'setState' | 'onPointer' | 'post' | 'columns'>,
): RenderElement {
  const { elements, state, setState, onPointer, post, columns } = surface
  const lines = props.lines
  const armedRange = props.armedRange
  const visualRows = visualRowsOf(lines, columns > 0 ? columns : Number.POSITIVE_INFINITY)

  onPointer(onPointerOf(lines, visualRows, state ?? null, armedRange, setState, (data) => post(data)))

  // A live drag takes over the drawing; otherwise an already-armed range (from a past drag)
  // stays highlighted, so the person can see what is about to ride their next prompt without
  // holding the mouse down.
  const dragRange = state == null ? null : orderedRangeOf(lines, state.anchor, state.current)
  const armedAsRange = armedRange === undefined ? null : { start: posOf(lines, armedRange.start), end: posOf(lines, armedRange.end) }
  const range = dragRange ?? armedAsRange

  const { Box } = elements
  return Box({
    key: 'root',
    flexDirection: 'column',
    children: visualRows.map((row, index) =>
      lineRowOf(elements, `row:${index}`, row.text, range === null ? null : rowSelectionOf(range, row, lines[row.line]?.length ?? 0)),
    ),
  })
}

const DraftSelection: ClientModule<DraftSelectionProps, State> = (props, surface) => drawDraftSelection(props, surface)

export default DraftSelection

